# Demo: greedy ASAP list-scheduling of 1F1B on p stages, lambda=0.
# fwd=f, bwd=ratio*f. bubble = 1 - busy/(p*makespan). Compare to formulas.
def sim_1f1b(p, m, f=1.0, ratio=1.0, lam=0.0):
    b = f*ratio
    # task (i,k,type): type 0=F,1=B ; deps: F(i,k) after F(i-1,k)+lam ; B(i,k) after B(i+1,k)+lam and F(i,k)
    fin = {}
    def F(i,k): return ('F',i,k)
    def B(i,k): return ('B',i,k)
    mach_next = [0.0]*p  # machine available time
    def sched(task, dur):
        t, i, k, ty = task
        st = mach_next[i]
        if ty=='F':
            if i>0: st = max(st, fin[F(i-1,k)] + lam)
        else:
            st = max(st, fin[F(i,k)])
            if i<p-1: st = max(st, fin[B(i+1,k)] + lam)
        ft = st + dur
        mach_next[i] = ft
        fin[task] = ft
        return ft
    for i in range(p):
        nw = p-1-i
        order = [('F',i,k) for k in range(nw)]
        if i==p-1:
            for j in range(m):
                order += [('F',i,j),('B',i,j)]
        else:
            for j in range(m):
                order.append(('B',i,j))
                if nw+1+j < m: order.append(('F',i,nw+1+j))
            # deadlock guard: B0 on stage i before F(i,0) exists? F(i,j) for j<nw already placed;
            # remaining F placed in loop. B_j needs F(i,j): for j<=nw ok; for j>nw F placed at j-nw-1 iter -> before. ok
        for t in order:
            sched(t, f if t[0]=='F' else b)
    wall = max(fin.values())
    busy = m*(f+b)
    return wall, busy, 1 - busy*p/(p*wall)/1*0 + (1 - (busy)/(wall))  # per-rank idle frac
for p in (2,4,8):
    for m in (4*p, 8*p):
        for ratio in (1.0,2.0):
            wall,busy,idle = sim_1f1b(p,m,1.0,ratio)
            c1 = (p-1)/(m+p-1)                    # classic, fwd=bwd slot
            print(f"p={p} m={m} r={ratio}: sim_idle={idle:.4f} (p-1)/(m+p-1)={c1:.4f}")
EOF
