def sim(p,m,f=1.0,ratio=1.0,lam=0.0):
    # per-stage machine order (canonical 1F1B); event loop until all scheduled
    b=f*ratio; fin={}; mach=[0.0]*p; orders=[]; nxt=[0]*p
    for i in range(p):
        nw=p-1-i; o=[('F',k) for k in range(nw)]
        for j in range(m):
            o.append(('B',j))
            if nw+1+j<m: o.append(('F',nw+1+j))
        orders.append(o)
    left=sum(len(o) for o in orders)
    def ready(ty,i,k):
        if ty=='F':
            return i==0 or ('F',i-1,k) in fin
        if ('F',i,k) not in fin: return False
        return i==p-1 or ('B',i+1,k) in fin
    while left:
        prog=False
        for i in range(p):
            if nxt[i]<len(orders[i]):
                ty,k=orders[i][nxt[i]]
                if ready(ty,i,k):
                    st=mach[i]
                    if ty=='F' and i>0: st=max(st,fin[('F',i-1,k)]+lam)
                    if ty=='B':
                        st=max(st,fin[('F',i,k)])
                        if i<p-1: st=max(st,fin[('B',i+1,k)]+lam)
                    ft=st+(f if ty=='F' else b); mach[i]=ft; fin[(ty,i,k)]=ft
                    nxt[i]+=1; left-=1; prog=True
        if not prog: raise RuntimeError('stuck')
    wall=max(fin.values()); return wall, 1-m*(f+b)/wall
