        assert sorted(x for x in o)==sorted([('F',k) for k in range(m)]+[('B',k) for k in range(m)])
        orders.append(o)
    left=sum(len(o) for o in orders)
    def ready(ty,i,k):
        if ty=='F': return i==0 or ('F',i-1,k) in fin
        return ('F',i,k) in fin and (i==p-1 or ('B',i+1,k) in fin)
    while left:
        prog=False
        for i in range(p):
            if nxt[i]<len(orders[i]):
                ty,k=orders[i][nxt[i]]
                if ready(ty,i,k):
                    st=mach[i]
                    if ty=='F' and i>0: st=max(st,fin[('F',i-1,k)]+lam)
                    if ty=='B':
                        st=max(st,fin[('F',i,k)])
                        if i<p-1: st=max(st,fin[('B',i+1,k)]+lam)
                    ft=st+(f if ty=='F' else b); mach[i]=ft; fin[(ty,i,k)]=ft
                    nxt[i]+=1; left-=1; prog=True
        if not prog: raise RuntimeError('stuck')
    return max(fin.values())
